fn main() {
    let matches = cli().get_matches();
    if let Some((sub, sub_matches)) = matches.subcommand() {
        if sub == "completions" {
            let shell_str: &String = sub_matches.get_one("SHELL").unwrap();
            let shell = match shell_str.as_str() {
                "bash" => Shell::Bash,
                "elvish" => Shell::Elvish,
                "fish" => Shell::Fish,
                "powershell" => Shell::PowerShell,
                "zsh" => Shell::Zsh,
                _ => unreachable!(),
            };
            let mut cmd = cli();
            generate(shell, &mut cmd, "mdbook", &mut io::stdout());
        }
    }
}
