    #[serde(flatten)]
    pub extra: HashMap<String, toml::Value>,
}

impl Config {
    pub fn from_file(path: &Path) -> Result<Self, String> {
        if !path.exists() {
            let mut cfg = Config::default();
            // apply env overrides even when no file?
            cfg.update_from_env();
            return Ok(cfg);
        }
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        Self::from_toml_str(&content)
    }
    pub fn from_toml_str(s: &str) -> Result<Self, String> {
        // Parse as toml::Value first to handle errors with same message?
        // toml crate error display should match original
        let mut cfg: Config = toml::from_str(s).map_err(|e| e.to_string())?;
        cfg.update_from_env();
        Ok(cfg)
    }
    pub fn update_from_env(&mut self) {
        log::debug!(target: "mdbook_core::config", "Updating the config from environment variables");
        // Collect MDBOOK_ vars
        // Serialize config to toml::Value, apply overrides, deserialize back?
        // Simpler: convert to serde_json::Value via toml::Value?
        let mut val = toml::Value::try_from(&*self).unwrap_or(toml::Value::Table(Default::default()));
        for (k, v) in std::env::vars() {
            if !k.starts_with("MDBOOK_") { continue; }
            let rest = &k["MDBOOK_".len()..];
            if rest.is_empty() { continue; }
            // Split by __ for nesting, then convert _ to - and lowercase?
            // Spec: remove prefix, turn to kebab-case, __ separates nested, _ -> -
            // Example: MDBOOK_FOO_bar__baz -> foo-bar.baz
            // Steps: split by __, for each part: replace _ with -, lowercase?
            // Actually spec says: Double underscores separate nested keys, single underscore replaced with dash.
            // And case-insensitive? MDBOOK_FOO -> foo (lowercase). MDBOOK_foo -> foo.
            // So lowercase everything? Let's do: rest.split("__"), for each segment: segment.replace('_', "-").to_lowercase()
            let parts: Vec<String> = rest.split("__").map(|s| s.replace('_', "-").to_lowercase()).collect();
            // Parse value as JSON, fallback to string
            let parsed: toml::Value = match serde_json::from_str::<serde_json::Value>(&v) {
                Ok(jv) => json_to_toml(jv),
                Err(_) => toml::Value::String(v.clone()),
            };
            // Insert into val
            insert_nested(&mut val, &parts, parsed);
        }
        // Deserialize back
        if let Ok(new_cfg) = val.try_into::<Config>() {
            *self = new_cfg;
        }
    }
    pub fn get_book_src(&self) -> String { self.book.src.clone() }
    pub fn get_build_dir(&self) -> String { self.build.build_dir.clone() }
}

fn json_to_toml(v: serde_json::Value) -> toml::Value {
    match v {
        serde_json::Value::Null => toml::Value::String("null".to_string()), // toml has no null? But original? For env override, JSON null? Probably not used. We'll map to string?
        serde_json::Value::Bool(b) => toml::Value::Boolean(b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() { toml::Value::Integer(i) }
            else if let Some(f) = n.as_f64() { toml::Value::Float(f) }
            else { toml::Value::String(n.to_string()) }
        },
        serde_json::Value::String(s) => toml::Value::String(s),
        serde_json::Value::Array(a) => toml::Value::Array(a.into_iter().map(json_to_toml).collect()),
        serde_json::Value::Object(o) => {
            let mut m = toml::map::Map::new();
            for (k,v) in o { m.insert(k, json_to_toml(v)); }
            toml::Value::Table(m)
        }
    }
}

fn insert_nested(root: &mut toml::Value, parts: &[String], val: toml::Value) {
    if parts.is_empty() { return; }
    // Ensure root is table
    if !matches!(root, toml::Value::Table(_)) {
        *root = toml::Value::Table(Default::default());
    }
    let mut cur = root;
    for (i, part) in parts.iter().enumerate() {
        let is_last = i == parts.len()-1;
        if let toml::Value::Table(map) = cur {
            if is_last {
                // If both existing and new are tables/objects, merge? For MDBOOK_BOOK='{"title":...}' case, parts=["book"], val is table. Should merge with existing book table, not replace? Original merges? Let's see: MDBOOK_BOOK='{"title":...}' should override title but keep other book fields? Probably merges. Our simple insert would replace entire book table, losing other fields. Need to merge if both tables.
                if let Some(existing) = map.get(part) {
                    if let (toml::Value::Table(existing_map), toml::Value::Table(new_map)) = (existing, &val) {
                        let mut merged = existing_map.clone();
                        for (k,v) in new_map { merged.insert(k.clone(), v.clone()); }
                        map.insert(part.clone(), toml::Value::Table(merged));
                        return;
                    }
                }
                map.insert(part.clone(), val.clone());
                return;
            } else {
                if !map.contains_key(part) {
                    map.insert(part.clone(), toml::Value::Table(Default::default()));
                } else {
                    // if existing is not table, replace with table? Or keep? Original probably replaces?
                    if !matches!(map.get(part), Some(toml::Value::Table(_))) {
                        map.insert(part.clone(), toml::Value::Table(Default::default()));
                    }
                }
                cur = map.get_mut(part).unwrap();
            }
        } else {
            return;
        }
    }
}

