pub fn get_html_config(output: &HashMap<String, toml::Value>) -> toml::map::Map<String, toml::Value> {
    if let Some(v) = output.get("html") {
        if let toml::Value::Table(m) = v { return m.clone(); }
    }
    toml::map::Map::new()
}
pub fn get_toml_str(map: &toml::map::Map<String, toml::Value>, key: &str, default: Option<&str>) -> Option<String> {
    map.get(key).and_then(|v| match v {
        toml::Value::String(s) => Some(s.clone()),
        _ => None,
    }).or_else(|| default.map(|s| s.to_string()))
}
pub fn get_toml_bool(map: &toml::map::Map<String, toml::Value>, key: &str, default: bool) -> bool {
    map.get(key).and_then(|v| match v {
        toml::Value::Boolean(b) => Some(*b),
        _ => None,
    }).unwrap_or(default)
}
pub fn get_toml_string_array(map: &toml::map::Map<String, toml::Value>, key: &str) -> Vec<String> {
    map.get(key).and_then(|v| match v {
        toml::Value::Array(a) => Some(a.iter().filter_map(|x| match x { toml::Value::String(s) => Some(s.clone()), _ => None }).collect()),
        toml::Value::String(s) => Some(vec![s.clone()]),
        _ => None,
    }).unwrap_or_default()
}
