        numbered.push(SummaryItem::Link(link));
        let idx = numbered.len() - 1;
        stack.push((indent, vec![idx]));
    } else {
        // Nested: parent is top of stack
        let parent_path = stack.last().unwrap().1.clone();
        // Navigate to parent's nested_items via path
