    // Also need to handle "----" (4 dashes)? Should be separator (at least 3). Good.
    // What about "--- with trailing spaces"? Probably not separator (since contains spaces). But what about "---\n" (no trailing spaces)? That's separator.
    // Implement: if line matches r"^(-{3,}|\*{3,}|_{3,})$" then true, else false.
    // Note: line from .lines() strips \n, but keeps other spaces? Yes, .lines() strips \r\n, but keeps leading/trailing spaces? Actually .lines() splits on \n and strips \r? It keeps other spaces. Good.
    if line.is_empty() { return false; }
    let mut chars = line.chars();
    let first = chars.next().unwrap();
    if first != '-' && first != '*' && first != '_' { return false; }
    if line.len() < 3 { return false; }
    for c in line.chars() {
        if c != first { return false; }
    }
    true
}

fn parse_list_marker(line: &str) -> Option<(usize, String, usize)> {
    // Returns (indent, rest, marker_col)
    // indent: count of leading spaces/tabs (tab=4? Or 1? For column, tab=1? For nesting, tab=4? Let's use spaces=1, tab=4 for indent, but column = byte index +1 (tab counts as 1 char)? Actually column in error message is probably byte column? For tab indent, what column would it report? Need to test. For now, column = leading whitespace chars count +1 (tab counts as 1).
    // Check: line[indent..] starts with "-" or "*" + space/tab?
    // In markdown, list marker must be followed by space/tab? What about "-[A](a.md)" without space? Probably not list, ignored. Let's require space/tab after marker.
    let mut indent_chars = 0;
    let mut indent_width = 0; // for nesting: spaces=1, tab=4
    let mut byte_idx = 0;
    for c in line.chars() {
        if c == ' ' { indent_chars += 1; indent_width += 1; byte_idx += 1; }
        else if c == '\t' { indent_chars += 1; indent_width += 4; byte_idx += 1; }
        else { break; }
    }
    let rest_start = byte_idx;
    if rest_start >= line.len() { return None; }
    let after_indent = &line[rest_start..];
    if !(after_indent.starts_with('-') || after_indent.starts_with('*')) {
        return None;
    }
    // Check next char after marker is space/tab? What about end of line? "-"? Alone? Probably not list. Require space/tab.
    let marker = after_indent.chars().next().unwrap();
    let after_marker = &after_indent[marker.len_utf8()..];
    if after_marker.is_empty() { return None; }
    let next_c = after_marker.chars().next().unwrap();
    if next_c != ' ' && next_c != '\t' {
        return None;
    }
    // Skip spaces/tabs after marker to get rest
    let mut rest_idx = rest_start + marker.len_utf8();
    for c in after_marker.chars() {
        if c == ' ' || c == '\t' { rest_idx += c.len_utf8(); } else { break; }
    }
    let rest = line[rest_idx..].to_string();
    let marker_col = indent_chars + 1; // 1-indexed column of marker
    Some((indent_width, rest, marker_col))
}

