fn parse_list_marker(line: &str) -> Option<(usize, String, usize)> {
    let mut indent_chars = 0;
    let mut indent_width = 0;
    let mut byte_idx = 0;
    for c in line.chars() {
        if c == ' ' { indent_chars += 1; indent_width += 1; byte_idx += 1; }
        else if c == '\t' { indent_chars += 1; indent_width += 4; byte_idx += 1; }
        else { break; }
    }
    if byte_idx >= line.len() { return None; }
    let after_indent = &line[byte_idx..];
    if !(after_indent.starts_with('-') || after_indent.starts_with('*')) {
        return None;
    }
    let marker = after_indent.chars().next().unwrap();
    let after_marker = &after_indent[marker.len_utf8()..];
    if after_marker.is_empty() { return None; }
    let next_c = after_marker.chars().next().unwrap();
    if next_c != ' ' && next_c != '\t' {
        return None;
    }
    let mut rest_idx = byte_idx + marker.len_utf8();
    for c in after_marker.chars() {
        if c == ' ' || c == '\t' { rest_idx += c.len_utf8(); } else { break; }
    }
    let rest = line[rest_idx..].to_string();
    let marker_col = indent_chars + 1;
    Some((indent_width, rest, marker_col))
}

fn parse_link_in_text(text: &str) -> Option<(String, Option<String>)> {
    let trimmed = text.trim_start();
    if !trimmed.starts_with('[') {
        return None;
    }
    let close_bracket_paren = trimmed.find("](")?;
    let name = trimmed[1..close_bracket_paren].to_string();
    let after = &trimmed[close_bracket_paren+2..];
    let close_paren = after.find(')')?;
    let inside = &after[..close_paren];
    let inside_trimmed = inside.trim();
    if inside_trimmed.is_empty() {
        return Some((name, Some("".to_string())));
    }
    let dest = if inside_trimmed.starts_with('<') {
        let end = inside_trimmed.find('>')?;
        inside_trimmed[1..end].to_string()
    } else {
        let parts: Vec<&str> = inside_trimmed.split_whitespace().collect();
        if parts.len() == 1 {
