                        while let Some((top_indent, _)) = numbered_stack.last() {
                            if *top_indent < indent { break; }
                            numbered_stack.pop();
                        }
                        if numbered_stack.is_empty() {
                            numbered.push(SummaryItem::Link(link));
                            let pos = numbered.len() - 1;
                            numbered_stack.push((indent, vec![pos]));
