fn count_leading(line: &str) -> (usize, bool) {
    let mut spaces = 0;
    let mut has_tab = false;
    for c in line.chars() {
        if c == ' ' { spaces += 1; }
        else if c == '\t' { has_tab = true; break; }
        else { break; }
    }
    (spaces, has_tab)
}

fn is_separator(line: &str) -> bool {
    let mut leading = 0;
    for c in line.chars() {
        if c == ' ' { leading += 1; }
        else if c == '\t' { return false; }
        else { break; }
    }
    if leading >= 2 { return false; }
    let rest = line[leading..].trim_end();
    if rest.is_empty() { return false; }
    for c in rest.chars() {
        if c != '-' && c != '*' && c != '_' && c != ' ' && c != '\t' {
            return false;
        }
    }
    let without_spaces: String = rest.chars().filter(|&c| c != ' ' && c != '\t').collect();
    if without_spaces.len() < 3 { return false; }
    let first = without_spaces.chars().next().unwrap();
    if first != '-' && first != '*' && first != '_' { return false; }
    for c in without_spaces.chars() {
        if c != first { return false; }
    }
    true
}

fn parse_list_marker(line: &str) -> Option<(usize, String, usize)> {
    let mut indent_chars = 0;
    let mut indent_width = 0;
    let mut byte_idx = 0;
    for c in line.chars() {
        if c == ' ' { indent_chars += 1; indent_width += 1; byte_idx += 1; }
        else if c == '\t' { indent_chars += 1; indent_width += 4; byte_idx += 1; }
        else { break; }
    }
    if byte_idx >= line.len() { return None; }
    let after_indent = &line[byte_idx..];
    if !(after_indent.starts_with('-') || after_indent.starts_with('*')) {
        return None;
    }
    let marker = after_indent.chars().next().unwrap();
    let after_marker = &after_indent[marker.len_utf8()..];
    if after_marker.is_empty() { return None; }
    let next_c = after_marker.chars().next().unwrap();
    if next_c != ' ' && next_c != '\t' {
        return None;
    }
    let mut rest_idx = byte_idx + marker.len_utf8();
    for c in after_marker.chars() {
        if c == ' ' || c == '\t' { rest_idx += c.len_utf8(); } else { break; }
    }
    let rest = line[rest_idx..].to_string();
    let marker_col = indent_chars + 1;
    Some((indent_width, rest, marker_col))
}

fn parse_link_in_text(text: &str) -> Option<(String, Option<String>)> {
    let trimmed = text.trim_start();
    if !trimmed.starts_with('[') {
        return None;
    }
    let close_bracket_paren = trimmed.find("](")?;
    let name = trimmed[1..close_bracket_paren].to_string();
    let after = &trimmed[close_bracket_paren+2..];
    let close_paren = after.find(')')?;
    let inside = &after[..close_paren];
    let inside_trimmed = inside.trim();
    if inside_trimmed.is_empty() {
        return Some((name, Some("".to_string())));
    }
    let dest = if inside_trimmed.starts_with('<') {
        let end = inside_trimmed.find('>')?;
        inside_trimmed[1..end].to_string()
    } else {
        let parts: Vec<&str> = inside_trimmed.split_whitespace().collect();
        if parts.len() == 1 {
            parts[0].to_string()
        } else {
            let title_part = inside_trimmed[parts[0].len()..].trim();
            let valid_title = (title_part.starts_with('"') && title_part.ends_with('"') && title_part.len() >= 2)
                || (title_part.starts_with('\'') && title_part.ends_with('\'') && title_part.len() >= 2)
                || (title_part.starts_with('(') && title_part.ends_with(')') && title_part.len() >= 2);
            if !valid_title {
                return None;
            }
            parts[0].to_string()
        }
    };
    Some((name, Some(dest)))
}

fn get_link_mut<'a>(items: &'a mut Vec<SummaryItem>, path: &[usize]) -> Option<&'a mut Link> {
    fn helper<'b>(items: &'b mut Vec<SummaryItem>, path: &[usize]) -> Option<&'b mut Link> {
        if path.is_empty() { return None; }
        let idx = path[0];
        if idx >= items.len() { return None; }
        match &mut items[idx] {
            SummaryItem::Link(link) => {
                if path.len() == 1 {
                    Some(link)
                } else {
                    helper_nested(&mut link.nested_items, &path[1..])
                }
            },
            _ => None,
        }
    }
    fn helper_nested<'b>(items: &'b mut Vec<SummaryItem>, path: &[usize]) -> Option<&'b mut Link> {
        if path.is_empty() { return None; }
        let idx = path[0];
        if idx >= items.len() { return None; }
        match &mut items[idx] {
            SummaryItem::Link(link) => {
                if path.len() == 1 {
                    Some(link)
                } else {
                    helper_nested(&mut link.nested_items, &path[1..])
                }
            },
            _ => None,
        }
    }
    helper(items, path)
}

fn assign_numbers(items: &mut Vec<SummaryItem>, prefix: &mut Vec<u32>) {
    let mut count = 0u32;
    for item in items.iter_mut() {
        match item {
            SummaryItem::Link(link) => {
                count += 1;
                let mut num = prefix.clone();
                num.push(count);
                link.number = Some(SectionNumber(num.clone()));
                let mut nested_prefix = num;
                assign_numbers_vec(&mut link.nested_items, &mut nested_prefix);
            },
            _ => {}
        }
    }
}

fn assign_numbers_vec(items: &mut Vec<SummaryItem>, prefix: &mut Vec<u32>) {
    let mut count = 0u32;
    for item in items.iter_mut() {
        match item {
            SummaryItem::Link(link) => {
                count += 1;
                let mut num = prefix.clone();
                num.push(count);
                link.number = Some(SectionNumber(num.clone()));
                let mut nested_prefix = num;
                assign_numbers_vec(&mut link.nested_items, &mut nested_prefix);
            },
            _ => {}
        }
    }
}
