pub struct Heading {
    pub level: u32,
    pub id: String,
    pub text: String, // raw text for ID? Or html?
}

#[derive(Debug, Clone)]
pub struct FootnoteDef {
    pub label: String,
    pub content: String, // markdown content?
    pub number: usize,
}

