    lines: Vec<String>,
    opts: &'a MarkdownOptions,
    pos: usize,
    headings: Vec<Heading>,
    heading_ids: HashMap<String, usize>, // for duplicates
    footnotes: HashMap<String, String>, // label -> content (raw)
