fn strip_code_spans_for_plain(s: &str) -> String {
    // Similar to extract_code_spans but return content without <code> tags
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '`' {
            let mut open_len = 0;
            while i + open_len < chars.len() && chars[i+open_len] == '`' { open_len += 1; }
            let mut j = i + open_len;
            let mut found = None;
            while j < chars.len() {
                if chars[j] == '`' {
                    let mut close_len = 0;
                    while j + close_len < chars.len() && chars[j+close_len] == '`' { close_len += 1; }
                    if close_len == open_len { found = Some(j); break; }
                    j += close_len;
                } else { j += 1; }
            }
            if let Some(close_pos) = found {
                let mut content: String = chars[i+open_len..close_pos].iter().collect();
                if content.starts_with(' ') && content.ends_with(' ') && content.trim().len() > 0 {
                    content = content[1..content.len()-1].to_string();
                }
                content = content.replace('\n', " ").replace('\r', " ");
                result.push_str(&content);
                i = close_pos + open_len;
                continue;
            } else {
                for _ in 0..open_len { result.push('`'); }
                i += open_len;
                continue;
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    result
}

