            if !trimmed_start.starts_with('[') { continue; }
            // Footnote defs start with "[^", skip (handled separately)
            if trimmed_start.starts_with("[^") { continue; }
            if let Some(close) = trimmed_start.find("]:") {
                let label = trimmed_start[1..close].trim().to_lowercase();
                if label.is_empty() { continue; }
                let after = trimmed_start[close+2..].trim();
                if after.is_empty() { continue; }
                // Parse url and optional title
                // url can be <url> or bare (no spaces). Title can be "title", 'title', (title).
                let (url, title) = if after.starts_with('<') {
