                               (rest.starts_with('(') && rest.ends_with(')') && rest.len()>=2) {
                                Some(rest[1..rest.len()-1].to_string())
                            } else { None }
                        };
                        (u, t)
                    } else { continue; }
                } else {
                    // Split by whitespace: first is url, rest is title?
                    let mut parts = after.split_whitespace();
                    let u = match parts.next() { Some(s) => s.to_string(), None => continue };
                    let rest: String = after[u.len()..].trim().to_string();
                    let t = if rest.is_empty() { None } else {
                        if (rest.starts_with('"') && rest.ends_with('"') && rest.len()>=2) ||
                           (rest.starts_with('\'') && rest.ends_with('\'') && rest.len()>=2) ||
                           (rest.starts_with('(') && rest.ends_with(')') && rest.len()>=2) {
                            Some(rest[1..rest.len()-1].to_string())
