fn parse_info_string(info: &str) -> (String, Vec<String>) {
    // Split by comma, space, tab? Docs: comma, space, or tab-separated. E.g., "rust,ignore", "rust ignore", "rust\tignore", "rust, ignore"? With spaces after comma? Probably trim each.
    // First token is lang, rest are attrs.
    // Info can be empty? Then lang "", attrs [].
    // Info can contain hidelines=... with =? That's attr with value. Good.
    // Split: use regex [,\s]+? Actually split on ',' or whitespace (space, tab)? And trim?
    // Example: "rust,ignore" -> ["rust","ignore"]. "rust ignore" -> ["rust","ignore"]. "rust, ignore" (comma + space) -> ["rust","ignore"] (empty between? Actually split on [,\s]+ gives ["rust","ignore"]. Good.
    // Example: "python,hidelines=!!!" -> ["python","hidelines=!!!"]. Good.
    // Example: "" -> [] -> lang "", attrs [].
    // Example: "rust, editable" (with space) -> ["rust","editable"]. Good.
    if info.trim().is_empty() {
        return ("".to_string(), vec![]);
    }
    let parts: Vec<String> = info.split(|c| c == ',' || c == ' ' || c == '\t').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
    if parts.is_empty() {
        return ("".to_string(), vec![]);
    }
    let lang = parts[0].clone();
    let attrs = parts[1..].to_vec();
    (lang, attrs)
}

