        let lines: Vec<String> = c.split('\n').map(|l| if l.ends_with('\r') { l[..l.len()-1].to_string() } else { l.to_string() }).collect();
        Self { lines, opts: o, pos: 0, headings: vec![], hid: HashMap::new(), footnotes: HashMap::new(), forder: vec![], frefs: vec![], fcounts: HashMap::new(), html: String::new(), linkrefs: HashMap::new() }
