            if self.try_code() { continue; }
            if self.try_table() { continue; }
            if self.try_head() { continue; }
            if self.try_hr() { continue; }
            if self.try_quote() { continue; }
            if self.try_list() { continue; }
            if self.try_html() { continue; }
