            let def: Vec<(String, usize)> = ord.into_iter().filter(|(l,_)| self.footnotes.contains_key(l)).collect();
            if !def.is_empty() {
                self.html.push_str("<hr>\n<ol class=\"footnote-definition\">\n");
                for (lab, num) in def {
                    let c = self.footnotes.get(&lab).cloned().unwrap_or_default().replace('\n', " ");
                    let inner = self.inline(&c);
                    let cnt = self.frefs.iter().filter(|l| *l==&lab).count();
                    let mut bl = String::new();
                    for i in 1..=cnt { bl.push_str(&format!(" <a href=\"#fr-{}-{}\">\u{21a9}</a>", num, i)); }
                    self.html.push_str(&format!("<li id=\"footnote-{}\">\n<p>{}{}</p>\n</li>\n", num, inner, bl));
                }
                self.html.push_str("</ol>\n");
            }
        }
        (self.html, self.headings)
    }
