fn get_authors()->Vec<String> {
    // Run git config --get user.name in current dir
    let cwd = std::env::current_dir().unwrap_or(PathBuf::from("."));
    match std::process::Command::new("git").arg("config").arg("--get").arg("user.name").current_dir(&cwd).output() {
        Ok(out)=>{
            if out.status.success() {
                let s=String::from_utf8_lossy(&out.stdout).trim().to_string();
                if !s.is_empty() { return vec![s]; }
            }
            vec![]
        },
        Err(_)=>vec![],
    }
}
