fn generate_missing(items:&[crate::summary::SummaryItem], src:&Path)->Result<(),(String,Vec<String>)> {
    for it in items {
        match it {
            crate::summary::SummaryItem::Link(l)=>{
                if let Some(rel)=&l.location {
                    let full=src.join(rel);
                    if !full.exists() {
                        if let Some(p)=full.parent() { let _=std::fs::create_dir_all(p); }
                        let _=std::fs::write(&full, format!("# {}\n", l.name));
                    }
                }
                generate_missing(&l.nested_items, src)?;
            },
            _=>{},
        }
    }
    Ok(())
}
