fn split_cmd(s:&str)->Vec<String> {
    let mut res=vec![]; let mut cur=String::new(); let mut ins=false; let mut ind=false; let mut esc=false;
    for c in s.chars() {
        if esc { cur.push(c); esc=false; continue; }
        if c=='\\' { esc=true; continue; }
        if c=='\''&&!ind { ins=!ins; continue; }
        if c=='"'&&!ins { ind=!ind; continue; }
        if !ins&&!ind&&(c==' '||c=='\t'||c=='\n') { if !cur.is_empty() { res.push(cur.clone()); cur.clear(); } continue; }
        cur.push(c);
    }
    if !cur.is_empty() { res.push(cur); }
    res
}
